import sys
from collections import deque

def main():
    input = sys.stdin.readline
    N = int(input())
    S = input().strip()

    dq = deque()
    rev = False

    for k, ch in enumerate(S, 1):
        if ch == 'x':
            if rev:
                dq.appendleft(k)
            else:
                dq.append(k)
        else:  # ch == 'o'
            if rev:
                dq.appendleft(k)
                rev = False
            else:
                dq.append(k)
                rev = True

    ans = list(dq)
    if rev:
        ans.reverse()

    print(*ans)

if __name__ == "__main__":
    main()
