MOD = 998244353

def main():
    N = sys.stdin.readline().strip()
    digits = [ord(c) - ord('0') for c in N]

    M = 1025  # masks 0..1023 plus sentinel 1024
    S = 2 * 2 * 3 * 2 * M

    popcount = [0] * M
    for i in range(M):
        popcount[i] = i.bit_count()

    valid_masks = [m for m in range(1024) if popcount[m] <= 3]
    valid_masks.append(1024)

    pow2 = [1 << d for d in range(10)]

    dp = [0] * S

    # tight=1, started=0, rem=0, has3=0, mask=0
    initial_idx = ((((1 * 2 + 0) * 3 + 0) * 2 + 0) * M + 0)
    dp[initial_idx] = 1

    for limit_digit in digits:
        ndp = [0] * S

        for tight in (0, 1):
            max_digit = limit_digit if tight else 9

            for started in (0, 1):
                for rem in range(3):
                    for has3 in (0, 1):
                        base = (((tight * 2 + started) * 3 + rem) * 2 + has3) * M

                        for mask in valid_masks:
                            val = dp[base + mask]
                            if val == 0:
                                continue

                            for d in range(max_digit + 1):
                                if started == 0:
                                    if d == 0:
                                        ntight = 1 if (tight and d == limit_digit) else 0
                                        nstarted = 0
                                        nrem = 0
                                        nhas3 = 0
                                        nmask = 0
                                    else:
                                        ntight = 1 if (tight and d == limit_digit) else 0
                                        nstarted = 1
                                        nrem = d % 3
                                        nhas3 = 1 if d == 3 else 0
                                        nmask = pow2[d]
                                else:
                                    ntight = 1 if (tight and d == limit_digit) else 0
                                    nstarted = 1
                                    nrem = (rem * 10 + d) % 3
                                    nhas3 = has3 or (d == 3)

                                    if mask == 1024:
                                        nmask = 1024
                                    else:
                                        nm = mask | pow2[d]
                                        if popcount[nm] <= 3:
                                            nmask = nm
                                        else:
                                            nmask = 1024

                                nbase = (((ntight * 2 + nstarted) * 3 + nrem) * 2 + nhas3) * M
                                nidx = nbase + nmask

                                ndp[nidx] += val
                                if ndp[nidx] >= MOD:
                                    ndp[nidx] -= MOD

        dp = ndp

    ans = 0

    for tight in (0, 1):
        for rem in range(3):
            for has3 in (0, 1):
                base = (((tight * 2 + 1) * 3 + rem) * 2 + has3) * M

                for mask in valid_masks:
                    val = dp[base + mask]
                    if val == 0:
                        continue

                    is_multiple_of_3 = 1 if rem == 0 else 0
                    contains_3 = 1 if has3 == 1 else 0
                    exactly_three_digits = 1 if (mask != 1024 and popcount[mask] == 3) else 0

                    if is_multiple_of_3 + contains_3 + exactly_three_digits == 1:
                        ans += val
                        if ans >= MOD:
                            ans -= MOD

    print(ans)


