import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    T = int(data[0])
    out = []
    cache = {}

    for i in range(1, T + 1):
        K = int(data[i])

        if K in cache:
            out.append(cache[K])
            continue

        for q in range(1, 101):
            n = K * q
            s = str(n)
            if '00' in s:
                cache[K] = s
                out.append(s)
                break

    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
