import sys
import bisect

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    p = data[1:1 + n]

    max_so_far = 0
    records = 0
    non_records = []

    for v in p:
        if v > max_so_far:
            records += 1
            max_so_far = v
        else:
            non_records.append(v)

    tails = []
    for v in non_records:
        pos = bisect.bisect_left(tails, v)
        if pos == len(tails):
            tails.append(v)
        else:
            tails[pos] = v

    answer = records + len(tails)
    print(answer)

if __name__ == "__main__":
    main()
