import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    N = next(it)
    M = next(it)

    edges = []
    deg = [0] * (N + 1)
    edge_count = {}

    for _ in range(M):
        a = next(it)
        b = next(it)
        edges.append((a, b))
        deg[a] += 1
        deg[b] += 1

        if a > b:
            a, b = b, a
        key = (a, b)
        edge_count[key] = edge_count.get(key, 0) + 1

    u, v = edges[0]

    def count_with(x):
        found = None
        for a, b in edges:
            if a != x and b != x:
                found = (a, b)
                break

        if found is None:
            return N - 1

        a, b = found
        count = 0

        for y in (a, b):
            if y == x:
                continue
            key = (x, y) if x < y else (y, x)
            if deg[x] + deg[y] - edge_count.get(key, 0) == M:
                count += 1

        return count

    def is_valid(x, y):
        key = (x, y) if x < y else (y, x)
        return deg[x] + deg[y] - edge_count.get(key, 0) == M

    ans = count_with(u) + count_with(v)
    if is_valid(u, v):
        ans -= 1

    print(ans)


if __name__ == "__main__":
    main()
