import sys


def solve() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    a = data[1:1 + n]

    max_a = a[-1]
    pos = [-1] * (max_a + 1)

    for i, value in enumerate(a):
        pos[value] = i

    parent = [-1] * n

    def find(x: int) -> int:
        while parent[x] >= 0:
            if parent[parent[x]] >= 0:
                parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    ans = 0
    components = n

    for d in range(max_a, 0, -1):
        first_root = -1

        for multiple in range(d, max_a + 1, d):
            idx = pos[multiple]
            if idx == -1:
                continue

            if first_root == -1:
                first_root = find(idx)
            else:
                root = find(idx)
                if root == first_root:
                    continue

                if parent[first_root] > parent[root]:
                    first_root, root = root, first_root

                parent[first_root] += parent[root]
                parent[root] = first_root

                ans += d
                components -= 1

                if components == 1:
                    print(ans)
                    return

    print(ans)


if __name__ == "__main__":
    solve()
