MOD = 998244353

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]  # bytes

    parent = list(range(N))
    size = [1] * N

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    idx = 3
    for _ in range(M):
        a = int(data[idx]) - 1
        b = int(data[idx + 1]) - 1
        idx += 2
        union(a, b)

    comp_size = [0] * N
    for i in range(N):
        comp_size[find(i)] += 1

    comp_counts = {}
    for i, ch in enumerate(S):
        r = find(i)
        if comp_size[r] > 1:
            if r not in comp_counts:
                comp_counts[r] = [0] * 26
            comp_counts[r][ch - 97] += 1

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    product_mult = 1
    product_fact = 1
    flexible = False

    for r, cnts in comp_counts.items():
        n = comp_size[r]
        mult = fact[n]
        for c in cnts:
            if c >= 2:
                flexible = True
            mult = mult * invfact[c] % MOD
        product_mult = product_mult * mult % MOD
        product_fact = product_fact * fact[n] % MOD

    if flexible:
        ans = product_mult
    else:
        if not comp_counts:
            ans = 1
        else:
            inv2 = (MOD + 1) // 2
            ans = product_fact * inv2 % MOD

    print(ans)


if __name__ == "__main__":
    solve()
