import sys

def solve() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    T = next(it)
    out_lines = []

    for _ in range(T):
        N = next(it)
        M = next(it)
        A = [next(it) for _ in range(M)]

        total_weight = 0
        max_item = 0
        for i, a in enumerate(A):
            if a > 0:
                w = 1 << i
                total_weight += a * w
                if w > max_item:
                    max_item = w

        if total_weight == 0:
            out_lines.append("0")
            continue

        low = max(max_item, (total_weight + N - 1) // N)
        high = total_weight

        while low < high:
            mid = (low + high) // 2

            slots = N * (mid >> (M - 1))
            feasible = True

            for i in range(M - 1, -1, -1):
                if i < M - 1:
                    slots += N * ((mid >> i) & 1)
                if slots < A[i]:
                    feasible = False
                    break
                slots -= A[i]
                if i > 0:
                    slots *= 2

            if feasible:
                high = mid
            else:
                low = mid + 1

        out_lines.append(str(low))

    sys.stdout.write("\n".join(out_lines))

