import sys


def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    Q = int(next(it))

    S = [next(it) for _ in range(N)]

    # ones[i]: bit k is 1 iff S[k][i] == '1'
    ones = [0] * M
    for k, s in enumerate(S):
        bit = 1 << k
        for i, ch in enumerate(s):
            if ch == ord('1'):
                ones[i] |= bit

    allmask = (1 << N) - 1
    zeros = [allmask ^ ones[i] for i in range(M)]

    # mask[i][a][b] has bit j set iff there exists an initial string
    # whose i-th char is a and j-th char is b.
    mask = [[[0, 0], [0, 0]] for _ in range(M)]

    for i in range(M):
        oi = ones[i]
        zi = zeros[i]
        mi = mask[i]

        for j in range(M):
            oj = ones[j]
            zj = zeros[j]

            allowed = 0
            if zi & zj:
                allowed |= 1  # (0, 0)
            if zi & oj:
                allowed |= 2  # (0, 1)
            if oi & zj:
                allowed |= 4  # (1, 0)
            if oi & oj:
                allowed |= 8  # (1, 1)

            bitj = 1 << j
            if allowed & 1:
                mi[0][0] |= bitj
            if allowed & 2:
                mi[0][1] |= bitj
            if allowed & 4:
                mi[1][0] |= bitj
            if allowed & 8:
                mi[1][1] |= bitj

    answers = []

    for _ in range(Q):
        T = next(it)

        zero_pos = 0
        one_pos = 0

        for j, ch in enumerate(T):
            if ch == ord('0'):
                zero_pos |= 1 << j
            else:
                one_pos |= 1 << j

        ok = True

        for i, ch in enumerate(T):
            a = 1 if ch == ord('1') else 0

            # For every j with T[j] == 0, pair (T[i], 0) must be possible.
            if zero_pos & ~mask[i][a][0]:
                ok = False
                break

            # For every j with T[j] == 1, pair (T[i], 1) must be possible.
            if one_pos & ~mask[i][a][1]:
                ok = False
                break

        answers.append("Yes" if ok else "No")

    sys.stdout.write("\n".join(answers))


if __name__ == "__main__":
    solve()
