import sys
from collections import deque


class Dinic:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]

    def add_edge(self, u, v, c):
        self.adj[u].append([v, c, len(self.adj[v])])
        self.adj[v].append([u, 0, len(self.adj[u]) - 1])

    def max_flow(self, s, t):
        flow = 0
        INF = 10**18
        n = self.n

        while True:
            level = [-1] * n
            level[s] = 0
            q = deque([s])

            while q:
                u = q.popleft()
                for v, c, rev in self.adj[u]:
                    if c > 0 and level[v] < 0:
                        level[v] = level[u] + 1
                        q.append(v)

            if level[t] < 0:
                break

            it = [0] * n

            def dfs(u, f):
                if u == t:
                    return f

                for i in range(it[u], len(self.adj[u])):
                    it[u] = i
                    v, c, rev = self.adj[u][i]
                    if c > 0 and level[u] + 1 == level[v]:
                        ret = dfs(v, min(f, c))
                        if ret > 0:
                            self.adj[u][i][1] -= ret
                            self.adj[v][rev][1] += ret
                            return ret
                return 0

            while True:
                f = dfs(s, INF)
                if f == 0:
                    break
                flow += f

        return flow


def main():
    sys.setrecursionlimit(10000)
    input = sys.stdin.readline

    H, W = map(int, input().split())
    S = [input().strip() for _ in range(H)]

    id_grid = [[-1] * W for _ in range(H)]
    weights = []

    for i in range(H):
        for j in range(W):
            if S[i][j] != '#':
                id_grid[i][j] = len(weights)
                weights.append(1 if S[i][j] == '+' else -1)

    N = len(weights)
    s = N
    t = N + 1

    dinic = Dinic(N + 2)
    total_pos = 0

    for idx, w in enumerate(weights):
        if w > 0:
            dinic.add_edge(s, idx, w)
            total_pos += w
        elif w < 0:
            dinic.add_edge(idx, t, -w)

    INF = 10**9

    for i in range(H):
        for j in range(W):
            if S[i][j] == '#':
                continue

            v = id_grid[i][j]

            # If cell v is kept, its left neighbor must also be kept.
            if j > 0 and S[i][j - 1] != '#':
                u = id_grid[i][j - 1]
                dinic.add_edge(v, u, INF)

            # If cell v is kept, its right neighbor must also be kept.
            if j + 1 < W and S[i][j + 1] != '#':
                u = id_grid[i][j + 1]
                dinic.add_edge(v, u, INF)

            # If cell v is kept, the cell directly above must also be kept.
            if i > 0 and S[i - 1][j] != '#':
                u = id_grid[i - 1][j]
                dinic.add_edge(v, u, INF)

    mincut = dinic.max_flow(s, t)
    answer = total_pos - mincut
    print(answer)


if __name__ == "__main__":
    main()
