    P = data[2:2 + N]
    queries = data[2 + N:2 + N + Q]

    prev = [0] * (N + 1)
    nxt = [0] * (N + 1)

    head = P[0]
    tail = P[-1]

    for i, v in enumerate(P):
        if i > 0:
            prev[v] = P[i - 1]
        if i + 1 < N:
            nxt[v] = P[i + 1]

