import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N = data[0]
    A = data[1:1 + N]

    # Möbius function up to N
    mu = [0] * (N + 1)
    mu[1] = 1
    primes = []
    is_comp = [False] * (N + 1)

    for i in range(2, N + 1):
        if not is_comp[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            v = i * p
            if v > N:
                break
            is_comp[v] = True
            if i % p == 0:
                mu[v] = 0
                break
            else:
                mu[v] = -mu[i]

    # Prefix sums of Möbius function
    pref = [0] * (N + 1)
    for i in range(1, N + 1):
        pref[i] = pref[i - 1] + mu[i]

    # T[i] = sum_{d=1}^{floor(N/i)} mu[d] * A_{i*d}
    T = [0] * (N + 1)
    for i in range(1, N + 1):
        total = 0
        d = 1
        for j in range(i, N + 1, i):
            total += mu[d] * A[j - 1]
            d += 1
        T[i] = total

    maxA = max(A)
    L = maxA
    R = None
    possible = True

    for i in range(1, N + 1):
        m = pref[N // i]
        t = T[i]

        if m > 0:
            # C >= ceil(t / m)
            lb = -((-t) // m)
            if lb > L:
                L = lb
        elif m < 0:
            # C <= floor(t / m)
            ub = t // m
            if R is None or ub < R:
                R = ub
        else:
            if t > 0:
                possible = False

    if not possible or (R is not None and L > R):
        print(-1)
    else:
        # Every operation increments A_1, so total operations = C - A_1.
        # The minimal feasible C is L.
        print(L - A[0])


