import random

def weighted_median(pairs, W):
    random.shuffle(pairs)
    target = (W + 1) // 2
    arr = pairs
    need = target
    while True:
        pivot = arr[0]
        num_p, den_p, w_p = pivot
        less = []
        greater = []
        w_less = 0
        w_equal = 0
        for item in arr:
            num, den, w = item
            left = num * den_p
            right = num_p * den
            if left < right:
                less.append(item)
                w_less += w
            elif left > right:
                greater.append(item)
            else:
                w_equal += w
        if need <= w_less:
            arr = less
        elif need <= w_less + w_equal:
            return num_p, den_p
        else:
            need -= w_less + w_equal
            arr = greater

def min_abs_linear(a_list, b_list):
    pairs = []
    total_weight = 0
    for a, b in zip(a_list, b_list):
        if a != 0:
            num = b
            den = a
            if den < 0:
                num = -num
                den = -den
            pairs.append((num, den, abs(a)))
            total_weight += abs(a)
    if total_weight == 0:
        num_t, den_t = 0, 1
    else:
        num_m, den_m = weighted_median(pairs, total_weight)
        if num_m < -den_m:
            num_t, den_t = -1, 1
        elif num_m > den_m:
            num_t, den_t = 1, 1
        else:
            num_t, den_t = num_m, den_m
    S = 0
    for a, b in zip(a_list, b_list):
        S += abs(a * num_t - b * den_t)
    g = math.gcd(S, den_t)
    return S // g, den_t // g

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    N = data[0]
    A = data[1:1+N]
    B = data[1+N:1+2*N]
    p1, q1 = min_abs_linear(A, B)
    p2, q2 = min_abs_linear(B, A)
    if p1 * q2 <= p2 * q1:
        p, q = p1, q1
    else:
        p, q = p2, q2
    print(p, q)

if __name__ == "__main__":
