def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    N, K, T = data[0], data[1], data[2]
    A = data[3:3 + N]
    A.sort()

    cur = 0
    ans = 0
    i = 0

    while cur < T:
        # Use all existing intervals that start at or before cur
        while i < N and A[i] <= cur:
            if A[i] + K > cur:
                cur = A[i] + K
            i += 1

        if cur >= T:
            break

        # Determine the next target: either the next existing interval's start or T
        if i < N:
            target = A[i]
            if target > T:
                target = T
        else:
            target = T

        # Number of presses needed to cover from cur to target
        need = (target - cur + K - 1) // K
        ans += need
        cur += need * K

    print(ans)

