import sys
import math

def solve():
    N = int(sys.stdin.readline())

    # Maximum possible length L such that L! <= N
    maxL = 1
    fact = 1
    while fact * (maxL + 1) <= N:
        maxL += 1
        fact *= maxL

    ans = 0

    # Length 3
    if maxL >= 3:
        a = 1
        while True:
            prod1 = a * (a + 1) * (a + 2)
            if prod1 > N:
                break

            M = N // a
            s = math.isqrt(a * a + 8 * M)
            d = (s - 3 * a) // 4

            if d > 0:
                ans += d

            a += 1

    # Length >= 4
    for L in range(4, maxL + 1):
        a = 1
        while True:
            # Check if d = 1 is valid
            p = 1
            for i in range(L):
                p *= a + i
                if p > N:
                    break

            if p > N:
                break

            # Binary search for maximum d
            low = 1
            high = N
            while low <= high:
                mid = (low + high) // 2

                p = 1
                for i in range(L):
                    p *= a + i * mid
                    if p > N:
                        break

                if p <= N:
                    low = mid + 1
                else:
                    high = mid - 1

            ans += high
            a += 1

    print(ans)


if __name__ == "__main__":
    solve()

